@Serializable
data class Watching (
	val names: List<String>,
	val since: Long,
	val at: Long
)

/// A session, with what the clients show of it. Before its details are read an agent is only what the sidebar's rows
/// say of it (key, runtime, model, effort, process, pending, last turn): the rest is absent then.
@Serializable
data class Session (
	val key: String,
	val connect: String? = null,
	/// thread | all
	val scope: String? = null,
	val title: String? = null,
	val createdBy: String? = null,
	val boundTo: List<String>? = null,
	val creator: Creator? = null,
	val participants: List<Creator>? = null,
	/// claude | codex
	val runtime: RuntimeKind,
	val profile: String? = null,
	val profilePinned: Boolean? = null,
	val model: String? = null,
	val effort: String? = null,
	val fast: Boolean? = null,
	val runtimeSessionId: String? = null,
	val workspace: String? = null,
	val running: Boolean? = null,
	val createdAt: Long? = null,
	val lastActiveAt: Long? = null,
	val archivedAt: Long? = null,
	/// running | warm | cold
	val process: String,
	val turns: Long? = null,
	val pending: Long,
	val firstText: String? = null,
	val lastTurn: TurnSummary? = null,
	val statusText: String,
	/// accent | green | blue | red | neutral
	val tone: Tone,
	/// Its mark (run | block | failed), and in words.
	val mark: Badge? = null,
	val badgeText: String? = null,
	val titleText: String,
	val agentText: String,
	/// Its model as people call it (Opus 5.5).
	val modelName: String? = null,
	val maker: Maker? = null,
	val runtimeText: String,
	val processText: String? = null,
	/// How hard its runtime can think, lowest first.
	val efforts: List<String>,
	/// Its times in words, by field (`createdAt`, `lastActiveAt`, …).
	val time: Map<String, Stamp>? = null,
	/// On a connect's page: the chat it was last talked in; as a candidate to deliver into, described, and whether it
	/// is the one now.
	val chat: Long? = null,
	val description: String? = null,
	val current: Boolean? = null,
	/// Keeping watch (a `job_start` watch of its runs): its chat is a watching one. A station from before watches says none.
	val watch: Watching? = null
)

/// Where an agent stands.
typealias Status = String

/// How a connect's conversations become sessions.
typealias ConnectMode = String

@Serializable
data class SlackTokens (
	val appToken: String,
	val botToken: String
)

@Serializable
data class SlackIdentity (
	val team: String,
	val teamId: String,
	val url: String,
	val botUserId: String,
	val botName: String,
	/// Its bot's picture (the app's icon), when Slack says.
	val botImage: String? = null
)

/// A connect's link to Slack: disabled | no_tokens | starting | connected | reconnecting (`botUserId`, `lastError`,
/// `workspace`) | error (`error`).
@Serializable
data class ConnectState (
	val state: String,
	val botUserId: String? = null,
	val lastError: String? = null,
	val workspace: SlackIdentity? = null,
	val error: String? = null
)

@Serializable
data class Owner (
	val id: String,
	val name: String,
	/// As the core names them.
	val shown: PersonShown? = null
)

/// A link's dot.
typealias Presence = String

/// A connect, with its state and how it runs in words.
@Serializable
data class Connect (
	val id: String,
	val name: String,
	val team: String? = null,
	/// Its bot's picture in Slack, as last seen.
	val botImage: String? = null,
	val enabled: Boolean,
	val kind: String,
	/// multi-session | single-session
	val mode: ConnectMode,
	val requireMention: Boolean,
	val bind: Bind,
	val slack: SlackTokens,
	val connection: ConnectState,
	val createdBy: Owner? = null,
	val sessions: Long,
	val session: String? = null,
	val statusText: String,
	/// online | busy | error | offline
	val presence: Presence,
	val modeText: String,
	val modeShort: String,
	val runtimeText: String,
	val runText: String,
	/// Its bound model as people call it (Opus 5.5).
	val modelName: String? = null
)

@Serializable
data class EnvVar (
	val key: String,
	val secret: Boolean,
	val value: String
)

/// Discovered on the existing profile; credentials and transport settings never enter this view.
@Serializable
data class DecisionCapability (
	val state: String,
	val detail: String,
	val model: String? = null,
	val provider: String? = null
)

@Serializable
data class ProfileCheck (
	val decision: DecisionCapability? = null,
	/// Runtime → model → supported reasoning levels; absent on older stations.
	val modelEfforts: Map<String, Map<String, List<String>>>? = null,
	/// ok | login | failed | unknown
	val state: String,
	val detail: String,
	val models: List<String>? = null,
	val checkedAt: Long,
	/// Its times in words, by field (`createdAt`, `lastActiveAt`, …).
	val time: Map<String, Stamp>? = null
)

@Serializable
data class LoginJob (
	val profile: String,
	val runtime: RuntimeKind,
	/// starting | needs_code | needs_approval | verifying | done | failed | cancelled
	val state: String,
	val url: String? = null,
	val userCode: String? = null,
	val error: String? = null,
	val startedAt: Long,
	val expiresAt: Long
)

@Serializable
data class ProfileTrouble (
	val title: String,
	val detail: String,
	val next: String,
	/// check | quota | login | command | key | env
	val action: String,
	val label: String
)

/// Models of one series (Opus), newest first.
@Serializable
data class ModelSeries (
	val name: String,
	val models: List<String>
)

/// How a profile is shared between the workspace's stations (docs/station-share.md).
@Serializable
data class ProfileShare (
	/// The share's id: the same on every station that has the profile.
	val id: String,
	/// host: this station has it and lends it; user: a copy of another station's.
	val role: String,
	/// The station that has it.
	val host: String,
	/// The stations that may use it; absent: every station of the workspace.
	val allow: List<String>? = null,
	/// For a copy: whether its host answered lately (absent on the host).
	val reachable: Boolean? = null,
	/// On its host: the stations that have it (a copy, or borrowing it).
	val users: List<String>? = null
)

/// A profile, with its last check in words and its models' makers.
@Serializable
data class Profile (
	val id: String,
	val name: String,
	/// The signed-in subscription identity; independent of the editable display name.
	val email: String? = null,
	val runtime: RuntimeKind,
	val runtimes: List<RuntimeKind>,
	val access: Access,
	val home: String,
	val homeExists: Boolean,
	val model: String? = null,
	val models: List<String>,
	/// Models changed by the pending selection; None when no selection is being saved.
	val modelsSaving: List<String>? = null,
	val env: List<EnvVar>,
	val usedBy: List<String>,
	val loginCommand: String,
	/// On the machine's own login of its runtime: not edited (but for its models) or signed in here; removing it stops using that login.
	val machine: Boolean? = null,
	/// Whether a message to a running Claude Code turn moves what it waits on to the background first; None from a
	/// station older than the setting.
	val backgroundOnMessage: Boolean? = null,
	val fast: Boolean? = null,
	val check: ProfileCheck? = null,
	val login: LoginJob? = null,
	val quota: Quota? = null,
	val checkText: String,
	val checkTone: Tone,
	/// The first problem to resolve, with its next step; absent when nothing needs attention.
	val trouble: ProfileTrouble? = null,
	/// The kind of account it is listed under: claude (Claude's subscription), chatgpt, key (the rest). A station's
	/// profiles come by kind, in that order.
	val group: String? = null,
	/// That kind in words: Claude 订阅.
	val groupTitle: String? = null,
	/// The makers of its models, and of those its check found, by model.
	val makers: Map<String, Maker?>,
	/// Its models, its default and those its check found as people call them (Opus 5.5), by model.
	val names: Map<String, String>,
	/// Its models and those its check found, by series (Claude's biggest first, the rest by name; 其他 last), newest
	/// first: how the list to enable them from is laid out.
	val series: List<ModelSeries>,
	/// How many of the models it could run are enabled, in words.
	val modelsText: String,
	/// What can be enabled on it: what its provider lists, then whatever is enabled already, each once.
	val available: List<String>? = null,
	/// What it can do: `claude`, `codex`, `decision` (the automatic decisions). The core works it out from where its
	/// provider speaks and what its check found.
	val uses: List<String>? = null,
	/// What it can do, in words (Claude Code · Codex · 自动决策).
	val usesText: String? = null,
	/// The provider of a key from the list of API providers, and the mark of its maker (none: the generic one).
	val providerName: String? = null,
	val providerMark: String? = null,
	/// A model can be named by hand (a key on a listed provider: not every one lists its models).
	val canAddModel: Boolean? = null,
	/// A provider that only answers the automatic decisions (Jev): its models are the ones its decision probe found.
	val decisionOnly: Boolean? = null,
	val decisionModels: List<String>? = null,
	/// Where the decision probe is, in words (what it found, or why it found none).
	val decisionText: String? = null,
	/// Shared with the workspace's other stations, or another station's (absent: neither, or a station older than sharing).
	val share: ProfileShare? = null,
	/// The workspaces the station joined whose chats may run on it too (docs/multi-workspace.md; none: its home's
	/// only), as its home's managers set it (`profile.put` `input.workspaces`); to a member of a joined one, that one.
	val workspaces: List<String>? = null
)

@Serializable
data class TurnRecord (
	val id: String,
	val kind: String,
	val outcome: String? = null,
	val declared: String? = null,
	/// In today's words (TurnSummary::ending).
	val ending: String? = null,
	/// For waiting: at most how long, in seconds, until the agent is asked again (a station yet to update says none).
	val waitSeconds: Long? = null,
	val detail: String? = null,
	val startedAt: Long,
	val endedAt: Long? = null
)

@Serializable
data class Membership (
	val thread: Long,
	val session: String,
	val connect: String,
	val joinedAt: Long
)

@Serializable
data class Quote (
	val author: String,
	val text: String,
	val comment: String,
	val ts: String? = null,
	/// agent | person | page (a mark on a previewed page) | image (a numbered mark on an image)
	val role: String? = null,
	/// The name of the file, among the message's attachments, that goes with it (a preview mark's screenshot).
	val file: String? = null
)

/// A message as merged from its thread's entries. In a chat, the core says whose it is and who said it.
@Serializable
data class Message (
	val seq: Long,
	val thread: Long,
	val ts: String,
	/// person | agent | ember
	val authorKind: String,
	val author: String,
	val authorName: String? = null,
	val text: String,
	val attachments: List<Attachment>,
	val quotes: List<Quote>,
	/// An agent's post that ended its turn: final, block (the words from before; `ending` has today's).
	val declared: String? = null,
	/// all_done, need_decision, need_help: how the post ended its agent's turn. A station yet to update says nothing.
	val ending: String? = null,
	val createdAt: Long,
	val editedAt: Long? = null,
	/// Its times in words, by field (`createdAt`, `lastActiveAt`, …).
	val time: Map<String, Stamp>? = null
)

/// A thread: a Slack thread or a chat on still.fail's page.
@Serializable
data class ChatThread (
	val id: Long,
	/// "slack:<team id>" or "ember".
	val surface: String,
	val channel: String,
	val channelName: String? = null,
	val threadTs: String,
	val title: String? = null,
	val createdBy: String? = null,
	val creator: Creator? = null,
	val createdAt: Long,
	val sessions: List<Membership>,
	val last: Long,
	val lastMessage: Message? = null,
	val read: Long,
	val unread: Long,
	val people: List<Creator>,
	val firstText: String? = null,
	/// Its times in words, by field (`createdAt`, `lastActiveAt`, …).
	val time: Map<String, Stamp>? = null
)

/// Something a job said, and when; `ago` (3 分钟前) and `clock` (13:04, 9/27 13:04) put in by the core.
@Serializable
data class JobNotice (
	val at: Long,
	val text: String,
	val ago: String? = null,
	val clock: String? = null
)

/// A part of a job's line: `word` its state's word (coloured as its dot), `notice` what it said (in the text's colour),
/// none the rest.
@Serializable
data class JobPart (
	val text: String,
	val kind: String? = null
)

/// The chat an open job is in.
@Serializable
data class JobChat (
	val id: String,
	val title: String? = null,
	val archived: Boolean? = null
)

/// A background job an agent started (a web service when it has a port): shown by its name; the port is how the
/// station reaches a service, not for people.
@Serializable
data class Job (
	val id: String,
	/// The session that started it (a chat's agents each have their own).
	val session: String? = null,
	val name: String,
	/// running | exited | stopped | failed (a service that exited is being started again)
	val state: String,
	val port: Long? = null,
	val exitCode: Long? = null,
	val startedAt: Long,
	val endedAt: Long? = null,
	/// What it runs (sh -c).
	val command: String? = null,
	/// How often a service was started again after it ended.
	val restarts: Long? = null,
	/// What it said lately (`ember-job notify`), newest first: how people see what a long-running job is up to.
	val notices: List<JobNotice>? = null,
	/// Started to keep watch (`job_start` watch). A station from before watches says none.
	val watch: Boolean? = null,
	/// When its output last grew; absent when it has none.
	val outputAt: Long? = null,
	/// Its dot: up (a service up), live (a job alive), restart (a service being started again), fail, off (over).
	val tone: String? = null,
	/// A web service (it has a port).
	val service: Boolean? = null,
	/// A service whose page can be opened: up, or being started again.
	val open: Boolean? = null,
	/// Over, so clearing takes it away (stopped, failed, ended by itself; not a service started again).
	val ended: Boolean? = null,
	/// It matters now: up, alive, restarting, or died lately (a day).
	val current: Boolean? = null,
	/// Its state in a word (在线, 在盯着, 意外退出…), coloured as its dot.
	val word: String? = null,
	/// The line under its name, in parts (see `JobPart`).
	val meta: List<JobPart>? = null,
	/// Its state, how long, and how many notices, as a detail's head says it: 在盯着 · 3 分钟 · 2 条通知.
	val detail: String? = null,
	/// When its output last grew, in words: 最后输出 · 3 分钟前.
	val outputSaid: String? = null,
	/// How long it has been up: 3 小时.
	val age: String? = null,
	/// Among the open ones (`longJobs`): its station, that station's name when there are several, the chat it is in as
	/// the viewer's sidebar has it, and all that in a line (studio · 修登录 · 已归档).
	val station: String? = null,
	val stationName: String? = null,
	val chat: JobChat? = null,
	val whereText: String? = null
)

/// An agent of a chat: its session, the connect that started it, its profile, and what it can move to.
@Serializable
data class ChatAgent (
	val session: Session,
	val status: Status,
	val badge: Badge? = null,
	val connect: Connect? = null,
	val profile: Profile? = null,
	val profiles: List<RunnableProfile>,
	/// The models it can move to, as its model control offers them; the account it runs on now.
	val choices: List<ModelOption>,
	val account: RunnableProfile? = null,
	val attention: List<Attention>,
	/// When its running turn began; absent when none runs.
	val since: Long? = null,
	/// While it waits on work it started (its turn ended as waiting): since when, and for how long at most.
	val wait: AgentWait? = null,
	/// Seen starting its turn while the chat shows (not at work already when first seen): its activity comes in.
	val started: Boolean? = null,
	val turns: List<TurnRecord>,
	val threads: List<ChatThread>,
	/// Its background jobs, newest first; those with a port are web services, shown by their names.
	val jobs: List<Job>
)

/// A decision waiting in a chat (`ChatView.asks`).
@Serializable
data class ChatAsk (
	/// The post it is about (`decision.dismiss`, and where the bar jumps to).
	val seq: ULong,
	/// A card: its options are on that post.
	val card: Boolean,
	/// The viewer is the one to decide it.
	val mine: Boolean,
	/// What is wanted, in a line: the agent's need as it said it, else the post's first line.
	val text: String
)

/// An agent of a sidebar row, with what its mark shows.
@Serializable
data class RowAgent (
	val key: String,
	val runtime: RuntimeKind,
	val model: String? = null,
	val effort: String? = null,
	val process: String,
	val pending: Long,
	val lastTurn: TurnSummary? = null,
	val agentText: String,
	val maker: Maker? = null,
	val mark: Badge? = null,
	val statusText: String,
	val badgeText: String? = null,
	/// Keeping watch, as its session's `watch`.
	val watch: Watching? = null
)

/// Who said a row's last thing: an agent (its state riding on its picture), a person, or ember.
@Serializable
data class LastBy (
	/// agent | person | ember
	val kind: String,
	val name: String,
	val mine: Boolean,
	val model: String? = null,
	val runtime: RuntimeKind? = null,
	/// block | run | failed
	val state: Badge? = null,
	val id: String? = null,
	val picture: String? = null,
	/// What its picture says when pointed at: who, and an agent's state.
	val label: String,
	val maker: Maker? = null
)

/// A row's last message, its text cut to 200 characters; `preview` its line.
@Serializable
data class RowMessage (
	val seq: Long,
	val authorKind: String,
	val author: String,
	val authorName: String? = null,
	val text: String,
	val createdAt: Long,
	val by: LastBy? = null,
	val preview: String,
	/// Its times in words, by field (`createdAt`, `lastActiveAt`, …).
	val time: Map<String, Stamp>? = null
)

@Serializable
data class Origin (
	val teamName: String? = null,
	val channel: String,
	val channelName: String? = null,
	val threadTs: String
)

/// Someone in a chat, named as the core names them.
@Serializable
data class Person (
	val id: String,
	val name: String,
	val email: String? = null,
	val via: String,
	val shown: PersonShown
)

/// A watching chat (core, present.ts): what it watches in words (监控中：盯 CI), and what archiving it by hand asks
/// first (`ask`: it runs on in the archive).
@Serializable
data class RowWatch (
	val text: String,
	val ask: String
)

/// One answer a decision offers (an agent's block post with chat_post `options`): a short phrase that reads on its own,
/// a line on what it leads to, and whether the agent recommends it.
@Serializable
data class DecisionOption (
	val label: String,
	val detail: String? = null,
	val recommended: Boolean? = null
)

/// What an agent's message asks people to answer it with (core decisions.ts): `type` options (`options`, as shown: the
/// recommended one last; a tap answers, `decision.answer`) or text (a field to write in, with a `placeholder`;
/// `decision.reply`). A type a UI does not know: answered by writing in the chat.
@Serializable
data class MessageCard (
	/// The person the agent asks to decide, by email. Absent on legacy cards.
	val assignee: String? = null,
	/// Who needs to decide, in the viewer's words; prepared by the core.
	val assigneeText: String? = null,
	/// options | text | login
	val type: String,
	val options: List<DecisionOption>? = null,
	val placeholder: String? = null,
	/// An agent's request to use a vault item (docs/vault.md): the request's id. An app shows approving it (the options,
	/// then the person confirms: `vault.approve` with the option's scope, `vault.deny`) rather than answering in the chat;
	/// a web page says to approve it in the app.
	val vault: String? = null,
	/// A login card: the login's id on its station (the `machineLogin` topic has the rest).
	val login: String? = null,
	/// A login card for a login on another station than the chat's: that station's key.
	val station: String? = null
)

/// A chat's card still pending (a row's, a chat page's; named for when the only cards were decisions): its post's entry,
/// the card as shown, an options card's options in the order they are shown (the recommended one last; empty for a
/// text card), whether the viewer dismissed it, and its line (奏 · …) while it is the viewer's.
@Serializable
data class RowDecision (
	val seq: Long,
	val options: List<DecisionOption>,
	/// The card itself. A core before cards says none: an options card.
	val card: MessageCard? = null,
	val dismissed: Boolean? = null,
	/// 奏 · <the post's first line, cut to about 40 characters>. Absent once dismissed.
	val text: String? = null
)

/// Whom a chat is shared with, as its row says (`ChatItem.xshare`).
@Serializable
data class RowShare (
	/// The workspaces' ids.
	val to: List<String>,
	/// Their agents may send messages in it.
	val write: Boolean
)

/// An item of the sidebar, as its station puts it together for the viewer, and where it is.
@Serializable
data class ChatItem (
	val id: String,
	val session: String,
	val thread: Long? = null,
	val title: String,
	val agents: List<RowAgent>,
	val last: RowMessage? = null,
	val unread: Boolean,
	val mine: Boolean,
	val lastActiveAt: Long,
	val connect: String? = null,
	val origin: Origin? = null,
	val station: String,
	val stationName: String,
	/// Its station's emoji, when its workspace gave it one and has more stations than it.
	val stationEmoji: String? = null,
	/// Its station's icon, when its workspace gave it one and has more stations than it: as StationView `icon`.
	val stationIcon: String? = null,
	/// block | run | failed
	val state: Badge? = null,
	/// Where it came from (Slack · workspace · #channel), for a Slack chat.
	val originText: String? = null,
	/// Its station is offline, in words ("Studio 离线"): the row is shown greyed and marked. Absent while online.
	val offline: String? = null,
	/// Its station's link coming back, or failing and retried, in words ("正在重连 Studio…"): the row is marked with a
	/// turning ring. Absent while linked (and while offline).
	val reconnecting: String? = null,
	/// Its times in words, by field (`createdAt`, `lastActiveAt`, …).
	val time: Map<String, Stamp>? = null,
	/// A new chat asked for here that its station has not made yet. Absent otherwise.
	val pending: Boolean? = null,
	/// Who is in it, for its pictures: who started it first, then everyone who wrote in it, each once. From a
	/// station that does not say: absent.
	val people: List<Person>? = null,
	/// Who started it, as in `people`.
	val creator: Creator? = null,
	/// Its people in words, who started it said ("小王 发起 · Lina、你"), with `people`.
	val peopleText: String? = null,
	/// The key a chat asked for here went by before its station made it: the list keeps it one row throughout. Older stations do not say it.
	val clientKey: String? = null,
	/// Pinned by the viewer to the top of their list. Absent when its station does not know pins (it cannot be pinned).
	val pinned: Boolean? = null,
	/// A watching chat (one of its agents keeps watch): archiving it by hand asks first. Absent otherwise.
	val watch: RowWatch? = null,
	/// The card it waits on (an agent's post with a card no one has answered yet), as the viewer sees it. Absent when
	/// there is none (and from a station before decisions).
	val decision: RowDecision? = null,
	/// Nothing is left in it: each of its agents ended all_done, nothing at work, no card waiting for the viewer,
	/// nothing unread; where its station's archive review is on, only once the review recommended archiving it. Drawn faded,
	/// below the rest of its day (the core orders it so). Absent otherwise.
	val settled: Boolean? = null,
	/// With `settled`: offer to archive it with one tap (`chat.archive`). Absent otherwise.
	val archivable: Boolean? = null,
	/// Where it stands, in words, for its second line, its agents' states first: 要你帮忙：…, 出问题：…; then 奏 · … (a
	/// card waiting for the viewer, even while an agent works); then 在等：…, 做完了(：…). Absent while it is at work with
	/// no card waiting, or with nothing to say.
	val stateText: String? = null,
	/// The message `stateText` is about (a seq in this chat): the one the agent's state names. Opening the chat from
	/// the line may go to it. Absent when none, and for a line that asks for a decision (its chat leads to it: `ChatView.asks`).
	val stateAbout: Long? = null,
	/// Its mark, the most urgent first: alert (an agent failed), wait (a card waits, not dismissed by the viewer; or an
	/// agent needs them: need_help), busy (at work), done (something unread). Absent for none.
	val tone: String? = null,
	/// The other workspaces it is shared with (docs/chat-share.md). Absent when none, and from stations before sharing.
	val xshare: RowShare? = null,
	/// Another workspace's chat, its name: the `@` menu's `elsewhere` lists them after the workspace's own. Absent for
	/// the workspace's own.
	val outside: String? = null
)

/// A day of the list, with its heading (今天, 昨天, 星期三, 9月20日); or, above them all, the chats the viewer pinned
/// (`pinned`, `daysAgo` -1, headed 已固定).
@Serializable
data class ChatDay (
	val daysAgo: Long,
	val at: Double,
	val label: String,
	val items: List<ChatItem>,
	val pinned: Boolean? = null
)

/// A chat's services and background jobs as its pages show them (the `chatJobs` view): every one, those that matter
/// now first (died, restarting, up and alive, over; newest first within each); what the button's dot says; each
/// group's head's note; how many matter now, how many are over and whose they are (clearing them is per session).
@Serializable
data class ChatJobsView (
	val jobs: List<Job>,
	/// fail: one died lately; restart: a service is being started again.
	val alarm: String? = null,
	/// 2 个在线，1 个在重启; 1 个在盯着 (empty: nothing to say).
	val servicesNote: String,
	val jobsNote: String,
	val current: Long,
	val ended: Long,
	/// The sessions whose jobs that are over clearing takes away (`job.clearEnded` each).
	val clear: List<String>,
	/// 全部 5 个; 清掉 2 个已结束的; 另有 2 个已停止或结束.
	val allText: String,
	val clearText: String,
	val hiddenText: String
)

/// Who said a message, as its line shows them: an agent by its label and mark, a person by name and picture.
@Serializable
data class MessageBy (
	val name: String,
	val agent: String? = null,
	val maker: Maker? = null,
	val runtime: RuntimeKind? = null,
	val picture: String? = null,
	/// Another chat's agent (session_send): that chat's link, its name opens it.
	val from: String? = null,
	/// In a chat's page: its agent is one of the chat's, its name opens its execution history. Absent otherwise.
	val here: Boolean? = null
)

/// Where a decision in a chat's messages stands (core, decisions.ts): still waiting (no person has written since it was
/// asked, and no newer one replaced it), or `resolved`, with who answered and whether by picking an option.
@Serializable
data class MessageDecision (
	val resolved: Boolean,
	/// Still waiting, and the viewer dismissed it (off their list; the options still work).
	val dismissed: Boolean? = null,
	/// Who answered it (the first person to write after it), by name; absent while it waits, or when a newer decision
	/// replaced it.
	val answeredBy: String? = null,
	/// The option they picked (their message quoted it with an option's label), its label.
	val chosen: String? = null,
	/// Resolved, in words: 林晓 选了「先不改」, 林晓 回复了, 已换成新的问题.
	val text: String? = null
)

/// A place a message came from or went to: a chat on still.fail's page (`session`: the agent it opens), or a Slack thread.
@Serializable
data class Place (
	/// A still.fail chat's title, or a Slack thread's workspace and channel (`Cue#ops`).
	val name: String,
	/// ember | slack
	val surface: String,
	val session: String? = null,
	/// A Slack thread's link in Slack, while a connect is signed in to its workspace.
	val url: String? = null
)

/// A message in Slack an agent of a chat sent (chat_post to a Slack thread, slack_api chat.postMessage) or was given,
/// read from its transcript: the chat shows it after the message it followed, without it being one of the chat's.
@Serializable
data class ChatSentElsewhere (
	val key: String,
	/// The message it comes after (its seq); 0 before the first of the chat.
	val after: Long,
	val createdAt: Long,
	/// As sent (Slack's mrkdwn).
	val text: String,
	/// Where it went; none when the core cannot name it.
	val place: Place? = null,
	val failed: Boolean? = null,
	/// A person's message in Slack its agent was given (`by`: who said it); absent for what the agent sent there.
	val received: Boolean? = null,
	val by: MessageBy,
	/// Its times in words, by field (`createdAt`).
	val time: Map<String, Stamp>? = null
)

/// A message of a chat, with what the core decides of it: the viewer's (their bubble), still.fail's own notice, who said
/// it, and whether its agents have yet to take it.
@Serializable
data class ChatMessage (
	/// The local outbox identity this message replaced, when sent from this core.
	val outgoing: String? = null,
	val seq: Long,
	val thread: Long,
	val ts: String,
	/// person | agent | ember
	val authorKind: String,
	val author: String,
	val authorName: String? = null,
	val text: String,
	val attachments: List<Attachment>,
	val quotes: List<Quote>,
	/// An agent's post that ended its turn: final, block (the words from before; `ending` has today's).
	val declared: String? = null,
	/// all_done, need_decision, need_help: how the post ended its agent's turn. A station yet to update says nothing.
	val ending: String? = null,
	val createdAt: Long,
	val editedAt: Long? = null,
	val mine: Boolean,
	val system: Boolean,
	/// still.fail's notice about one of the station's profiles (its sign-in failed): that profile's id, for a link to it.
	val profile: String? = null,
	val by: MessageBy,
	val waiting: Boolean,
	/// Said while the chat shows (told as it was said, not caught up on): it comes in rather than being there at once.
	/// Decided by the core once, when first seen (attend.ts).
	val said: Boolean? = null,
	/// Its times in words, by field (`createdAt`).
	val time: Map<String, Stamp>? = null,
	/// An agent's post with an options card: the answers to pick, in the order they are shown (the one the agent
	/// recommends last), as `card.options`; drawn under the message. Absent for every other message.
	val options: List<DecisionOption>? = null,
	/// The card it carries (options to pick, or a text field), as shown. Absent for a message with none.
	val card: MessageCard? = null,
	/// With a card: whether it still waits for an answer, and who answered it how.
	val decision: MessageDecision? = null,
	/// In a chat's page: it asks what no one has decided and the viewer has not let go (one of the chat's `asks`, a card
	/// or an agent's need): letting it go (`decision.dismiss`) is offered under it. Absent otherwise.
	val asked: Boolean? = null,
	/// In a chat's page: the agent's last post, at the chat's end, saying it is all done, with nothing left in the chat
	/// (`archivable`): 归档 is offered under it. Absent otherwise.
	val archive: Boolean? = null,
	/// Under the same last all-done post: what the archive check made of the chat (the chat's `archiveCheck`).
	val archiveCheck: ArchiveCheck? = null,
	/// In a chat's page: what its agents sent to Slack or were given there after this message, before the next. Absent
	/// when nothing.
	val elsewhere: List<ChatSentElsewhere>? = null,
	/// In a chat's page: the names of the files its text places (`![](shot.png)`, `[the report](report.pdf)`), in the
	/// order it names them, drawn where it names them; the rest go below it. Absent when it places none (a person's
	/// words never do).
	val placed: List<String>? = null
)

/// A snapshot of a chat its station keeps for anyone with its link (`chat.publish` answers one too).
@Serializable
data class ChatPublished (
	/// `chat.unpublish` names it.
	val id: String,
	/// Its whole link (`https://share.still.fail/#<station key>.<id>.<key>`): anyone who has it can read it.
	val link: String,
	/// When it was published.
	val createdAt: Long,
	/// Who published it.
	val byName: String,
	/// The viewer may revoke it (who published it, or an owner or admin).
	val mayRevoke: Boolean,
	/// Its times in words (`createdAt`).
	val time: Map<String, Stamp>? = null
)

/// A chat made public, for its "…": what it has published, and whether the viewer may publish it.
@Serializable
data class ChatPublish (
	/// The viewer may publish it (not a read-only member).
	val may: Boolean,
	/// The snapshots its station keeps of it, the newest first (without those being revoked here).
	val links: List<ChatPublished>
)

/// A range of a text, `from` to `to` (UTF-16 units).
@Serializable
data class TextMark (
	val from: UInt,
	val to: UInt
)

/// A message a search's words found (`ChatSearchView.messages`): its chat opens at it (thread, seq).
@Serializable
data class FoundMessage (
	val station: String,
	val thread: Long,
	val seq: Long,
	/// Its chat, as the sidebar lists it.
	val chat: ChatItem,
	/// Who said it, as a chat names them (empty when not known).
	val by: String,
	/// The line of it that has the words, on one line, Markdown's marks out; `…` first when cut to the words.
	val text: String,
	/// Where the words are in `text` (UTF-16 ranges), in order.
	val marks: List<TextMark>,
	val createdAt: Long? = null,
	/// Its times in words, by field (`createdAt`).
	val time: Map<String, Stamp>? = null
)

/// The chats a few words find (the `chatSearch` topic): as the sidebar has them, those whose title has the words
/// first. What the composer's `@` menu and the switcher list.
@Serializable
data class ChatSearchView (
	val items: List<ChatItem>,
	/// The words looked for, as a found message marks them in its chat when opened (with `messages`).
	val words: List<String>? = null,
	/// The messages that have the words (asked for by `messages`, at most that many), newest first: only in the chats
	/// listed. Empty when not asked for.
	val messages: List<FoundMessage>? = null
)

/// A workspace a chat is shared with.
@Serializable
data class ChatShareTo (
	val workspace: String,
	val name: String
)

/// One of the viewer's other workspaces, and whether the chat is shared with it.
@Serializable
data class ChatSharePlace (
	val workspace: String,
	val name: String,
	/// The chat is shared with it.
	val on: Boolean
)

/// A chat's sharing with other workspaces, for its "…": its line, and what changing it offers.
@Serializable
data class ChatShare (
	/// The session its station keeps its sharing by (its thread's own, else its first): `chat.xshare` names it.
	val session: String,
	/// Where it is shared, in a line: 未分享, or the workspaces and 只读/可发消息 (`A、C · 只读`).
	val text: String,
	/// The workspaces it is shared with (what was asked here, until its station has it).
	val to: List<ChatShareTo>,
	/// Their agents may send messages in it, not only read it.
	val write: Boolean,
	/// The viewer may change it (the chat's starter, or an owner or admin of its workspace); else it is only shown.
	val may: Boolean,
	/// The viewer's other workspaces, to tick (`chat.xshare` takes those ticked).
	val places: List<ChatSharePlace>
)

/// Who is looking: the account that reaches the workspace, by its email.
@Serializable
